-- Imported by scripts/import-questions.ts from C:\Users\Cambo\Downloads\42DinosaurQuestions.json.

insert into public.questions (
  id, category, measure, subtype, prompt, answer, min, max, scale, unit,
  reference_year, source_title, source_url, explanation, is_daily
) values
  ('dinosaurs-length-spinosaurus-body-length', 'dinosaurs', 'size', 'length', 'Spinosaurus played the toothy villain of Jurassic Park III, but the real animal''s 2014 skeletal reconstruction put its body at about how many metres long?', 15, 6, 22, 'linear', 'metre', null, 'Spinosaurus aegyptiacus - Paul Sereno, University of Chicago', 'https://paulsereno.uchicago.edu/discoveries/spinosaurus_aegyptiacus/', 'A 2014 reconstruction led by Nizar Ibrahim put Spinosaurus aegyptiacus at roughly 15 metres, longer than a typical Tyrannosaurus rex and the longest predatory dinosaur known.', false),
  ('dinosaurs-event-tyrannosaurus-named', 'dinosaurs', 'history', 'event', 'Long before it starred in blockbuster films, in what year was Tyrannosaurus rex formally named by palaeontologist Henry Fairfield Osborn?', 1905, 1850, 1970, 'linear', 'year', null, '120th Anniversary of the Naming of Tyrannosaurus rex - Princeton University', 'https://geosciences.princeton.edu/news/120th-anniversary-naming-most-famous-dinosaur-all-time-tyrannosaurus-rex', 'Fossil hunter Barnum Brown collected the first T. rex bones in 1902 near Montana''s Hell Creek Formation, and Osborn gave the species its now-famous name three years later.', false),
  ('dinosaurs-event-triceratops-named', 'dinosaurs', 'history', 'event', 'In what year did Othniel Charles Marsh officially name Triceratops, after first mistaking its horn core for a giant bison?', 1889, 1840, 1960, 'linear', 'year', null, 'Triceratops horridus Marsh, 1889 - Smithsonian Institution', 'https://www.si.edu/object/triceratops-horridus-marsh-1889:nmnhpaleobiology_3572783', 'Marsh had labelled an 1887 horn find ''Bison alticornis''; once a complete skull turned up in 1888, he realised it belonged to a horned dinosaur and coined Triceratops the following year.', false),
  ('dinosaurs-percentage-big-john-completeness', 'dinosaurs', 'quantity', 'percentage', 'Big John, the record-breaking Triceratops sold at a Paris auction, is officially documented as what percentage complete?', 60, 0, 100, 'linear', 'percent', null, 'Largest Triceratops skeleton - Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/676000-largest-triceratops-skeleton', 'Guinness World Records certifies Big John''s skeleton as 60% complete, still enough to make it the largest documented Triceratops ever found.', false),
  ('dinosaurs-speed-velociraptor-top-speed', 'dinosaurs', 'physics', 'speed', 'Movies show Velociraptor as a relentless sprinter, but modelling by Natural History Museum researchers suggests it could run over how many kilometres per hour?', 40, 10, 70, 'linear', 'kph', null, 'Vicious Velociraptor: tales of a turkey-sized dinosaur - Natural History Museum', 'https://www.nhm.ac.uk/discover/velociraptor-facts.html', 'Museum researcher David Button says leg-proportion modelling suggests Velociraptor could exceed 40 km/h in short bursts, quicker than any human sprinter but well short of ostrich-mimic dinosaurs.', false),
  ('dinosaurs-duration-trex-growth-spurt', 'dinosaurs', 'physics', 'duration', 'Bone growth-ring analysis shows Tyrannosaurus rex packed on most of its adult weight during a teenage growth spurt lasting about how many years?', 4, 1, 14, 'linear', 'duration-year', null, 'T. rex owes its giant size to the ultimate teenage growth spurt - EurekAlert! (Florida State University)', 'https://www.eurekalert.org/news-releases/533446', 'Growth-ring studies led by Gregory Erickson found T. rex gained roughly 2 kilograms a day between ages 14 and 18, then growth almost stopped for the rest of its life.', false),
  ('dinosaurs-length-giraffatitan-mount-height', 'dinosaurs', 'size', 'length', 'Berlin''s mounted Giraffatitan skeleton is the tallest dinosaur skeleton ever mounted, standing how many metres high?', 13.27, 6, 20, 'linear', 'metre', null, 'Tallest dinosaur skeleton mounted - Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/tallest-dinosaur-skeleton-mounted', 'The Museum fur Naturkunde Berlin mount, largely built from real Tanzanian fossils excavated from 1909, stands 13.27 metres tall, about the height of a four-storey building.', false),
  ('dinosaurs-length-patagotitan-femur', 'dinosaurs', 'size', 'length', 'Patagotitan, one of the heaviest land animals ever weighed by scientists, had a single thighbone measuring how many metres end to end?', 2.4, 1, 4, 'linear', 'metre', null, 'Patagotitan mayorum - Encyclopaedia Britannica', 'https://www.britannica.com/list/titanosaurs-8-of-the-worlds-biggest-dinosaurs', 'One recovered Patagotitan femur measures 2.4 metres, taller than most adult humans, and was part of the haul that let scientists estimate the animal''s overall size.', false),
  ('dinosaurs-length-mamenchisaurus-neck', 'dinosaurs', 'size', 'length', 'A 2023 fossil analysis credited Mamenchisaurus sinocanadorum with the longest neck ever confidently reconstructed for any dinosaur, measuring about how many metres?', 15.1, 6, 24, 'linear', 'metre', null, 'New Fossil Analysis Reveals Dinosaur with Record-Holding 15-Meter-Long Neck - Stony Brook Medicine', 'https://news.stonybrookmedicine.edu/news/new-fossil-analysis-reveals-dinosaur-with-record-holding-15-meter-long-neck-2/', 'At about 15.1 metres, this Jurassic sauropod''s neck alone was longer than a school bus and more than six times the length of a giraffe''s neck.', false),
  ('dinosaurs-length-dreadnoughtus-body-length', 'dinosaurs', 'size', 'length', 'Dreadnoughtus, an exceptionally complete titanosaur unearthed in Patagonia, measured about how many metres from snout to tail tip?', 26, 12, 42, 'linear', 'metre', null, 'Dreadnoughtus - Encyclopaedia Britannica', 'https://www.britannica.com/list/titanosaurs-8-of-the-worlds-biggest-dinosaurs', 'Named for its battleship-like invulnerability once fully grown, Dreadnoughtus stretched about 26 metres, and over 70% of its skeleton was recovered, unusually complete for a giant sauropod.', false),
  ('dinosaurs-mass-beibeilong-egg', 'dinosaurs', 'size', 'mass', 'The giant oviraptorosaur Beibeilong sinensis, known from the ''Baby Louie'' fossil, laid some of the largest dinosaur eggs on record, each weighing about how many kilograms?', 5, 1, 14, 'linear', 'kilogram', null, 'Perinate and eggs of a giant caenagnathid dinosaur from the Late Cretaceous of central China - Nature Communications', 'https://www.nature.com/articles/ncomms14952', 'Each Beibeilong egg reached about 45 centimetres long and 5 kilograms, yet the eggs were still tiny relative to the roughly 2-tonne adult that laid them.', false),
  ('dinosaurs-mass-shingopana', 'dinosaurs', 'size', 'mass', 'Shingopana songwensis, a small Tanzanian titanosaur named for its unusually wide neck, is estimated to have weighed about how many metric tonnes?', 5, 1, 15, 'linear', 'tonne', null, 'Titanosaurs: 8 of the World''s Biggest Dinosaurs - Encyclopaedia Britannica', 'https://www.britannica.com/list/titanosaurs-8-of-the-worlds-biggest-dinosaurs', 'At only about 5 tonnes, Shingopana was a lightweight among titanosaurs, dwarfed by relatives like Patagotitan that weighed more than ten times as much.', false),
  ('dinosaurs-event-argentinosaurus-named', 'dinosaurs', 'history', 'event', 'A single fossil vertebra once mistaken for petrified wood eventually led to Argentinosaurus being formally described in what year?', 1993, 1950, 2020, 'linear', 'year', null, 'Argentinosaurus - Encyclopaedia Britannica', 'https://www.britannica.com/list/titanosaurs-8-of-the-worlds-biggest-dinosaurs', 'A rancher found the human-sized bone fragment in 1987, and it took six more years of study before scientists recognised it as a single vertebra from one of the largest dinosaurs known.', false),
  ('dinosaurs-duration-triassic-period', 'dinosaurs', 'physics', 'duration', 'The Triassic Period, when the very first dinosaurs walked the Earth, lasted about how many years according to the US National Park Service''s geologic timescale?', 51400000, 20000000, 90000000, 'linear', 'duration-year', null, 'Triassic Period - 251.9 to 201.3 MYA - National Park Service', 'https://www.nps.gov/articles/000/triassic-period.htm', 'Spanning about 51.4 million years, the Triassic began with a mass extinction, saw the first dinosaurs and pterosaurs appear, and ended with another die-off at its close.', false),
  ('dinosaurs-duration-jurassic-period', 'dinosaurs', 'physics', 'duration', 'The Jurassic Period, the ''Golden Age of Dinosaurs'' that produced giants like Stegosaurus, lasted about how many years according to the US National Park Service?', 56300000, 25000000, 95000000, 'linear', 'duration-year', null, 'Jurassic Period - 201.3 to 145.0 MYA - National Park Service', 'https://www.nps.gov/articles/000/jurassic-period.htm', 'At about 56.3 million years, the Jurassic ran longer than the Triassic before it, giving sauropods and stegosaurs tens of millions of years to grow to enormous sizes.', false),
  ('dinosaurs-duration-bone-wars', 'dinosaurs', 'physics', 'duration', 'The fossil-hunting rivalry between Othniel Marsh and Edward Cope, known as the Bone Wars, raged from 1877 until 1892, a feud lasting how many years?', 15, 3, 40, 'linear', 'duration-year', null, 'Bone Wars - Encyclopaedia Britannica', 'https://www.britannica.com/topic/Bone-Wars', 'Over those 15 years the two paleontologists bankrupted themselves competing to name new species, a rivalry that nonetheless filled American museums with dozens of newly discovered dinosaurs.', false),
  ('dinosaurs-percentage-species-named-since-1990', 'dinosaurs', 'quantity', 'percentage', 'According to a PNAS study estimating total dinosaur diversity, what percentage of all valid dinosaur species had been named after the year 1990?', 85, 0, 100, 'linear', 'percent', null, 'Estimating the diversity of dinosaurs - PNAS', 'https://www.pnas.org/doi/10.1073/pnas.0606028103', 'Better excavation techniques and new fossil-rich regions mean the vast majority of named dinosaur species have been described within the last few decades, not in the Victorian era most people picture.', false),
  ('dinosaurs-event-austroposeidon-named', 'dinosaurs', 'history', 'event', 'Fossils of Brazil''s largest known titanosaur, Austroposeidon magnificus, sat unstudied in a museum after their 1953 excavation until they were finally described as a new species in what year?', 2016, 1980, 2026, 'linear', 'year', null, 'Austroposeidon magnificus - Encyclopaedia Britannica', 'https://www.britannica.com/list/titanosaurs-8-of-the-worlds-biggest-dinosaurs', 'The partial vertebral column had been excavated near Sao Paulo decades earlier, but only when Brazilian researchers had the resources to study it properly did it become the country''s largest known titanosaur.', false),
  ('dinosaurs-count-coelophysis-ghost-ranch', 'dinosaurs', 'quantity', 'count', 'A single half-acre hillside at New Mexico''s Ghost Ranch yielded more than how many individual Coelophysis skeletons in one of the densest dinosaur bonebeds ever found?', 1000, 200, 3000, 'linear', 'count', null, 'Ghost Ranch: Fossil Site That Keeps Giving - American Museum of Natural History', 'https://www.amnh.org/explore/videos/shelf-life/ghost-ranch-fossil-site', 'Discovered by an AMNH team led by Edwin Colbert in 1947, the Ghost Ranch quarry preserved a mass die-off of this early, roughly 2-metre-long Triassic predator in astonishing numbers.', false),
  ('dinosaurs-count-psittacosaurus-juveniles', 'dinosaurs', 'quantity', 'count', 'A single Psittacosaurus fossil block from China preserves one adult surrounded by how many juveniles, offered as evidence of dinosaur parental care?', 34, 5, 80, 'linear', 'count', null, 'Parental care in an ornithischian dinosaur - Nature', 'https://www.nature.com/articles/431145a', 'The 2004 Nature study found the adult and 34 young crowded into less than half a square metre, though later analysis suggests an older sibling, not a parent, may have done the minding.', false),
  ('dinosaurs-count-maiasaura-nests', 'dinosaurs', 'quantity', 'count', 'Montana''s Egg Mountain site, the discovery that first proved dinosaurs cared for their young, contained how many Maiasaura nests clustered together?', 14, 2, 40, 'linear', 'count', null, 'Egg Mountain, the Two Medicine, and the Caring Mother Dinosaur - National Park Service', 'https://www.nps.gov/articles/mesozoic-egg-mountain-dawson-2014.htm', 'Jack Horner''s 1978 discovery of 14 nests packed into one Montana hillside gave Maiasaura its name, meaning ''caring mother lizard'', and reshaped how scientists viewed dinosaur behaviour.', false),
  ('dinosaurs-mass-maiasaura-adult', 'dinosaurs', 'size', 'mass', 'A Maiasaura hatchling weighed under a kilogram, but the National Park Service says it reached an adult mass of about how many kilograms within just 8 to 10 years?', 2000, 500, 5000, 'linear', 'kilogram', null, 'Egg Mountain, the Two Medicine, and the Caring Mother Dinosaur - National Park Service', 'https://www.nps.gov/articles/mesozoic-egg-mountain-dawson-2014.htm', 'Growing from a sub-kilogram hatchling to roughly 2,000 kg, about the weight of a small car, in under a decade meant Maiasaura packed on weight far faster than most reptiles.', false),
  ('dinosaurs-count-auca-mahuevo-eggs', 'dinosaurs', 'quantity', 'count', 'Erosion at Argentina''s Auca Mahuevo site exposed a titanosaur nesting ground containing more than how many fossilised sauropod eggs?', 500, 100, 1500, 'linear', 'count', null, 'The Late Cretaceous nesting site of Auca Mahuevo (Patagonia, Argentina): Eggs, nests, and embryos of titanosaurian sauropods', 'https://palaeovertebrata.com/Articles/sendFile/186/published_article', 'Auca Mahuevo preserved over 500 eggs, some containing embryos with fossilised skin impressions, giving scientists their clearest look yet at how giant sauropods nested in colonies.', false),
  ('dinosaurs-speed-fastest-theropod-trackway', 'dinosaurs', 'physics', 'speed', 'A 2025 study of footprints in Inner Mongolia identified the fastest confirmed Cretaceous theropod trackway, showing a mid-sized dinosaur sprinting at about how many kilometres per hour?', 45, 15, 90, 'linear', 'kph', null, 'The fastest-running theropod trackway in the Cretaceous from Ordos, Inner Mongolia, China - Science China Earth Sciences', 'https://link.springer.com/article/10.1007/s11430-025-1657-7', 'The five-footprint trackway, with strides up to 5.3 metres long, set a new speed record for Cretaceous theropods, calculated directly from the spacing of the tracks rather than from bones.', false),
  ('dinosaurs-duration-nigersaurus-tooth-replacement', 'dinosaurs', 'physics', 'duration', 'Nigersaurus, a plant-eating dinosaur with hundreds of teeth arranged like a vacuum-cleaner mouth, replaced each individual tooth roughly how many days after it wore down?', 30, 5, 90, 'linear', 'day', null, 'Structural Extremes in a Cretaceous Dinosaur - PLOS ONE', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0001230', 'Paul Sereno''s team found Nigersaurus swapped out worn teeth as fast as one per month, a conveyor-belt system needed to keep chewing tough, low-lying Cretaceous vegetation.', false),
  ('dinosaurs-event-fighting-dinosaurs-discovery', 'dinosaurs', 'history', 'event', 'The famous ''Fighting Dinosaurs'' fossil, showing a Velociraptor and Protoceratops locked in mid-battle, was unearthed in Mongolia''s Gobi Desert in what year?', 1971, 1920, 2010, 'linear', 'year', null, 'Fighting Dinosaurs - AMNH', 'https://www.amnh.org/explore/ology/ology-cards/038-fighting-dinosaurs', 'A Polish-Mongolian expedition found the pair seemingly buried alive by a collapsing sand dune mid-fight, the most dramatic direct evidence of dinosaur combat ever recovered.', false),
  ('dinosaurs-length-deinocheirus-arm', 'dinosaurs', 'size', 'length', 'First known only from a giant pair of arms found in 1965, Deinocheirus holds the record for longest arms of any bipedal dinosaur at how many metres?', 2.4, 1, 4.5, 'linear', 'metre', null, 'Longest arms for a bipedal dinosaur - Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/405286-longest-arms-for-a-bipedal-dinosaur', 'Deinocheirus mirificus was a mystery for almost 50 years until more complete specimens, described in 2014, finally revealed the strange, sail-backed, duck-billed dinosaur those giant 2.4-metre arms belonged to.', false),
  ('dinosaurs-length-therizinosaurus-claw', 'dinosaurs', 'size', 'length', 'Therizinosaurus, a plant-eating relative of meat-eating dinosaurs, wielded the longest claws of any known animal, curving up to how many metres along their outer edge?', 0.91, 0.3, 1.6, 'linear', 'metre', null, 'Longest claws - Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/70357-longest-claws', 'At up to 91 centimetres, Therizinosaurus claws dwarf even a Tyrannosaurus rex''s 20-centimetre claws, though scientists think they were used for hooking vegetation, not slashing prey.', false),
  ('dinosaurs-length-parasaurolophus-crest', 'dinosaurs', 'size', 'length', 'Parasaurolophus''s hollow, tube-shaped head crest, thought to work like a natural trombone, could reach how many metres long in some adult specimens?', 1.8, 0.6, 3, 'linear', 'metre', null, 'Ontogeny in the tube-crested dinosaur Parasaurolophus (Hadrosauridae) and heterochrony in hadrosaurids', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3807589/', 'Air travelling through the looping internal tube of a roughly 1.8-metre crest is thought to have let Parasaurolophus bellow low-frequency calls across Cretaceous floodplains.', false),
  ('dinosaurs-count-nigersaurus-teeth', 'dinosaurs', 'quantity', 'count', 'Nigersaurus packed its squared-off jaw with more than 50 columns of constantly replaced teeth, adding up to how many teeth in total at any one time?', 500, 100, 1200, 'linear', 'count', null, 'What dinosaur has 500 teeth? Inside the conveyer belt jaw of Nigersaurus - National Geographic', 'https://www.nationalgeographic.com/science/article/what-dinosaur-has-500-teeth-nigersaurus', 'CT scans revealed up to nine replacement teeth stacked behind each visible one, giving this Cretaceous grazer a built-in lawn-mower jaw of more than 500 teeth.', false),
  ('dinosaurs-count-sophie-stegosaurus-bones', 'dinosaurs', 'quantity', 'count', 'Sophie, the most complete Stegosaurus skeleton on public display anywhere, is built from more than how many individual bones?', 300, 50, 700, 'linear', 'count', null, 'World''s most complete Stegosaurus goes on show - Natural History Museum', 'https://www.nhm.ac.uk/press-office/press-releases/world_s-most-complete-stegosaurus-goes-on-show.html', 'At 5.6 metres long, about the size of a large 4x4 vehicle, Sophie''s skeleton has over 300 bones and was missing only its left arm and the base of its tail when found.', false),
  ('dinosaurs-mass-giraffatitan', 'dinosaurs', 'size', 'mass', 'Laser-scanning the mounted Giraffatitan skeleton in Berlin, researchers calculated a body mass of about how many tonnes, far lighter than older estimates?', 23.2, 8, 50, 'linear', 'tonne', null, 'How to weigh dinosaurs with lasers - National Geographic', 'https://www.nationalgeographic.com/science/article/weigh-dinosaur-with-lasers', 'Earlier 1960s estimates had ballooned to 80 tonnes, but scanning the actual Berlin mount and modelling its soft tissue brought the figure down to about 23.2 tonnes.', false),
  ('dinosaurs-length-big-john-combat-wound', 'dinosaurs', 'size', 'length', 'A keyhole-shaped puncture in Big John the Triceratops''s skull, likely made by a rival''s horn, measures about how many metres along its longest axis?', 0.2, 0.05, 0.6, 'linear', 'metre', null, 'Histological and chemical diagnosis of a combat lesion in Triceratops - Scientific Reports', 'https://www.nature.com/articles/s41598-022-08033-2', 'The 20-centimetre lesion in Big John''s squamosal bone shows signs of healing, meaning this Triceratops survived the fight by at least six months before it eventually died.', false),
  ('dinosaurs-percentage-spinosaurus-tail-completeness', 'dinosaurs', 'quantity', 'percentage', 'The Moroccan excavation that revealed Spinosaurus''s paddle-like tail recovered a specimen described as what percentage complete, the most complete Spinosaurus tail ever found?', 80, 0, 100, 'linear', 'percent', null, 'Bizarre Spinosaurus makes history as first known swimming dinosaur - National Geographic', 'https://www.nationalgeographic.com/science/article/first-spinosaurus-tail-found-confirms-dinosaur-was-swimming', 'Excavated bone by bone between 2018 and 2019, the nearly 80%-complete tail''s tall, paddle-shaped fin was the strongest evidence yet that Spinosaurus spent much of its life swimming.', false),
  ('dinosaurs-length-chicxulub-crater-diameter', 'dinosaurs', 'size', 'length', 'The buried Chicxulub crater, marking the asteroid strike that ended the age of dinosaurs, spans roughly how many kilometres across?', 180, 80, 320, 'linear', 'kilometre', null, 'Chicxulub Impact Event - Lunar and Planetary Institute', 'https://www.lpi.usra.edu/science/kring/Chicxulub/discovery/', 'At about 180 kilometres across, Chicxulub ranks among the largest confirmed impact craters on Earth, though it remains hidden beneath the Yucatan Peninsula and Gulf of Mexico.', false),
  ('dinosaurs-length-chicxulub-tsunami-height', 'dinosaurs', 'size', 'length', 'Computer models of the Chicxulub impact show open-ocean waves in the Gulf of Mexico topping how many metres high about an hour after the asteroid struck?', 300, 100, 600, 'linear', 'metre', null, 'The Chicxulub Impact Produced a Powerful Global Tsunami - AGU Advances', 'https://agupubs.onlinelibrary.wiley.com/doi/10.1029/2021AV000627', 'The 2022 simulation found wave heights that exceeded 300 metres near the impact site, with a tsunami energetic enough to scour ocean-floor sediment as far away as modern-day New Zealand.', false),
  ('dinosaurs-duration-chicxulub-dust-lifetime', 'dinosaurs', 'physics', 'duration', 'A 2023 climate model found fine dust from the Chicxulub impact lingered in Earth''s atmosphere and cooled the planet''s surface for as long as how many years?', 15, 4, 45, 'linear', 'duration-year', null, 'VUB research shows that fine particulates signalled the end of the dinosaurs - Vrije Universiteit Brussel', 'https://press.vub.ac.be/vub-research-shows-that-fine-particulates-signalled-the-end-of-the-dinosaurs', 'Researchers found the micrometre-sized silicate dust stayed aloft for up to 15 years, cooling Earth''s surface by as much as 15 degrees Celsius during that stretch.', false),
  ('dinosaurs-duration-photosynthesis-shutdown', 'dinosaurs', 'physics', 'duration', 'That same dust cloud blocked so much sunlight that global photosynthesis was suspended for almost how many years after the Chicxulub impact?', 2, 0.5, 8, 'linear', 'duration-year', null, 'VUB research shows that fine particulates signalled the end of the dinosaurs - Vrije Universiteit Brussel', 'https://press.vub.ac.be/vub-research-shows-that-fine-particulates-signalled-the-end-of-the-dinosaurs', 'With plants unable to photosynthesise for almost two years, food chains collapsed worldwide; only species that could go dormant, like seed-bearing plants and burrowing animals, tended to survive.', false),
  ('dinosaurs-percentage-deccan-traps-post-impact', 'dinosaurs', 'quantity', 'percentage', 'Precise dating published in Science found that what percentage of the Deccan Traps'' total lava volume erupted only after the Chicxulub asteroid struck?', 75, 0, 100, 'linear', 'percent', null, 'The eruptive tempo of Deccan volcanism in relation to the Cretaceous-Paleogene boundary - Science', 'https://www.eurekalert.org/news-releases/823313', 'Over 75% of the flood-basalt province erupted after the asteroid hit, suggesting the impact itself may have triggered a surge in volcanism rather than volcanism alone causing the extinction.', false),
  ('dinosaurs-count-chicxulub-tsunami-sites', 'dinosaurs', 'quantity', 'count', 'To confirm the Chicxulub impact triggered a truly global tsunami, researchers cross-checked their computer models against how many geological sites worldwide?', 120, 30, 300, 'linear', 'count', null, 'End-Cretaceous asteroid caused massive global tsunami, peaking at a mile high - AGU Newsroom', 'https://news.agu.org/press-release/end-cretaceous-asteroid-caused-massive-global-tsunami-peaking-at-a-mile-high', 'Disturbed sediment layers matching the tsunami''s predicted path turned up at 120 sites, including in New Zealand, more than 12,000 kilometres from the impact site in Mexico.', false),
  ('dinosaurs-mass-allosaurus-big-al', 'dinosaurs', 'size', 'mass', 'Laser-scanning ''Big Al'', the most complete Allosaurus skeleton ever found, researchers modelled a living body mass of about how many kilograms?', 1500, 500, 4000, 'linear', 'kilogram', null, 'How Big was ''Big Al''? Quantifying mass predictions for Allosaurus - Palaeontologia Electronica', 'http://palaeo-electronica.org/2009_3/186/index.html', 'Big Al, a subadult Allosaurus from Wyoming, was modelled at around 1,500 kg, lighter than an adult of the species would eventually have grown to be.', false),
  ('dinosaurs-mass-beibeilong-adult', 'dinosaurs', 'size', 'mass', 'The giant oviraptorosaur that laid the record-sized ''Baby Louie'' eggs is estimated to have grown into an adult weighing about how many metric tonnes?', 2, 0.5, 6, 'linear', 'tonne', null, 'Perinate and eggs of a giant caenagnathid dinosaur from the Late Cretaceous of central China - Nature Communications', 'https://www.nature.com/articles/ncomms14952', 'A roughly 2-tonne parent laying eggs of just a few kilograms shows how small dinosaur eggs stayed relative to body size, since a rigid shell can only grow so large before it can no longer breathe or hatch.', false)
on conflict (id) do nothing;
